import gmpy2
import sys

# Batch Fermat Factorization Script
N = 
chunk_size = 100000

def fermat_factor(N, start, chunk_size):
    for i in range(start, start + chunk_size):
        a = i
        b2 = a * a - N
        if b2 >= 0 and gmpy2.is_square(b2):
            b = gmpy2.isqrt(b2)
            p = a - b
            q = a + b
            if p * q == N:
                return p, q
    return None, None

if __name__ == '__main__':
    start = int(sys.argv[1]) if len(sys.argv) > 1 else int(gmpy2.isqrt(N))

    p, q = fermat_factor(N, start, chunk_size)

    if p and q:
        print(f"Factors found: p = {p}, q = {q}")
    else:
        print(f"Factors not found in this range: {start} to {start + chunk_size}")
